script.code:
const allData = {{workflowparams:allData}};
const unique = `${allData.to_created_by || ""}_${Date.now()}`;

return {
  unique
};

const allData = {{workflowparams:allData}}

// A bundle is ONE row of table_to with the bundle's items under `children`. The
// bundle row carries the number of bundles and its items carry their own
// quantities, so both are listed -- an item under a bundle by `#parent/child`.
// A bundle whose items are all zero goes as the bundle, since fillbackHeaderFields
// drops the whole thing together.
const isBundleParent = (row) => Boolean(row.item_bundle_id) && !row.material_id;
const childrenOf = (row) => (Array.isArray(row.children) ? row.children : []);

const zeroQtyArray = [];
for (const [index, to] of allData.table_to.entries()) {
  if (isBundleParent(to)) {
    const children = childrenOf(to);
    const zeroChildren = [];

    children.forEach((child, childIndex) => {
      if (child.to_qty <= 0) {
        zeroChildren.push(`#${index + 1}/${childIndex + 1}`);
      }
    });

    if (children.length === 0 || zeroChildren.length === children.length) {
      zeroQtyArray.push(`#${index + 1}`);
    } else {
      zeroQtyArray.push(...zeroChildren);
    }

    continue;
  }

  if (to.to_qty <= 0) {
    zeroQtyArray.push(`#${index + 1}`);
  }
}
let hasZero = 0
let message = null;
if (zeroQtyArray.length > 0) {
  message = `Line${zeroQtyArray.length > 1 ? "s" : ""} ${zeroQtyArray.join(
    ", ",
  )} ha${
    zeroQtyArray.length > 1 ? "ve" : "s"
  } a zero deliver quantity, which may prevent processing.\nIf you proceed, it will delete the row with 0 deliver quantity. \nWould you like to proceed?`;
  hasZero = 1
}

return {
  message,
  hasZero
};

const allData = {{workflowparams:allData}};
const tableTo = allData.table_to || [];

// A bundle is ONE row of table_to with the bundle's items under `children`. The
// bundle row holds no material, so the `row.material_id` guard below steps over
// it on its own; its items are rows in their own right and are allocated like
// any other line.
//
// rowIndex is the row's position in a flat walk of the tree. It is what the
// allocation tracker keys off to tell one row's allocation from another's, so it
// has to stay a unique whole number. parentIndex/childIndex is the address that
// writes the result back into the tree (childIndex null on a top-level row).
const rowsNeedingAllocation = [];
let flatIndex = 0;

const consider = (row, parentIndex, childIndex) => {
  const currentIndex = flatIndex;
  flatIndex += 1;

  const toQty = parseFloat(row.to_qty) || 0;
  const hasTempData = row.temp_qty_data && 
                      row.temp_qty_data !== "[]" && 
                      row.temp_qty_data.trim() !== "";

  // Only allocate if: has quantity AND no existing allocation AND has material_id
  if (toQty > 0 && !hasTempData && row.material_id) {
    rowsNeedingAllocation.push({
      rowIndex: currentIndex,
      parentIndex: parentIndex,
      childIndex: childIndex,
      materialId: row.material_id,
      quantity: toQty,
      uomId: row.to_order_uom_id,
      plantId: allData.plant_id,
      organizationId: allData.organization_id,
      soLineItemId: row.so_line_item_id || null
    });
  }
};

tableTo.forEach((row, index) => {
  consider(row, index, null);

  const children = Array.isArray(row.children) ? row.children : [];

  children.forEach((child, childIndex) => {
    consider(child, index, childIndex);
  });
});

// Initialize allocation tracker for cross-row deduplication
const allocationTracker = {};

return {
  rowsNeedingAllocation,
  allocationTracker,
  plantId: allData.plant_id,
  organizationId: allData.organization_id,
  totalRowsToAllocate: rowsNeedingAllocation.length
};

const allData = {{workflowparams:allData}};
const rowsNeedingAllocation = {{node:code_node_C58lS8pM.data.rowsNeedingAllocation}};

// Collect unique UOM IDs
const uomIds = new Set();
rowsNeedingAllocation.forEach(row => {
  if (row.uomId) uomIds.add(row.uomId);
});

return {
  uomIds: Array.from(uomIds)
};

const rowsNeedingAllocation = {{node:code_node_C58lS8pM.data.rowsNeedingAllocation}};
const currentIndexRaw = {{node:get_cache_node_aVQIWXIv.data}};
const index = currentIndexRaw ? parseInt(currentIndexRaw, 10) : 0;

const currentRow = rowsNeedingAllocation[index];

return {
  currentRow,
  currentIndex: index,
  nextIndex: index + 1
};

// executeAllocation - Updated with pendingReservedData priority (Production first)
// ============================================================================
// INPUTS
// ============================================================================
const currentRow = {{node:code_node_cvOKI9GU.data.currentRow}};
const itemData = {{node:get_node_pxY9Jxts.data.data}};
const isBatchManaged = itemData.item_batch_management === 1;
const pickingSetup = {{node:get_node_MX4rxQLm.data.data}};
const rawTracker = {{node:get_cache_node_j89l1u3S.data}};
let allocationTracker = {};

// 🔧 NEW: Pending reserved data (fetched from search node)
const pendingReservedData = {{node:search_node_ekF4IJPz.data.data}} || [];

if (rawTracker) {
  if (typeof rawTracker === 'string') {
    try {
      allocationTracker = JSON.parse(rawTracker);
    } catch (e) {
      console.log('Failed to parse allocation tracker, using empty object');
      allocationTracker = {};
    }
  } else if (typeof rawTracker === 'object') {
    allocationTracker = rawTracker;
  }
}

// Pre-fetched data
const allUOMs = {{node:search_node_sgKuGfeN.data.data}} || [];
const allBinLocations = {{node:search_node_d34w6rCv.data.data}} || [];

// Get balance data based on batch management
let balances = [];
let batchMasterData = [];

if (isBatchManaged) {
  batchMasterData = {{node:search_node_dg4nIIRM.data.data}} || [];
  balances = {{node:search_node_ojdgySof.data.data}} || [];
} else {
  balances = {{node:search_node_54hizGno.data.data}} || [];
}

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

// Get default bin for this item and plant
const getDefaultBin = (itemData, plantId) => {
  if (!itemData.table_default_bin?.length) return null;
  const entry = itemData.table_default_bin.find(bin => bin.plant_id === plantId);
  return entry?.bin_location || null;
};

// Get allocations from other rows of the same material (deduplication)
const getCurrentAllocations = (materialId, currentRowIndex, tracker) => {
  const materialAllocations = tracker[materialId] || {};
  const allocatedQuantities = {};

  Object.entries(materialAllocations).forEach(([rIdx, rowAllocs]) => {
    if (parseInt(rIdx) !== currentRowIndex) {
      Object.entries(rowAllocs).forEach(([locationKey, qty]) => {
        allocatedQuantities[locationKey] = (allocatedQuantities[locationKey] || 0) + qty;
      });
    }
  });

  return allocatedQuantities;
};

// Apply cross-row deduplication to balances
const applyAllocationsToBalances = (balances, allocatedQuantities, isBatchManaged) => {
  return balances.map(balance => {
    const key = isBatchManaged
      ? `${balance.location_id}-${balance.batch_id || "no_batch"}`
      : `${balance.location_id}`;

    const allocatedFromOthers = allocatedQuantities[key] || 0;
    const originalQty = balance.unrestricted_qty || 0;
    const adjustedQty = Math.max(0, originalQty - allocatedFromOthers);

    return {
      ...balance,
      unrestricted_qty: adjustedQty,
      original_unrestricted_qty: originalQty
    };
  });
};

// Find batch master data by batch_id
const findBatchData = (batchId) => {
  if (!isBatchManaged || !batchMasterData.length) return null;
  return batchMasterData.find(b => b.id === batchId) || null;
};

// Lookup bin location from pre-fetched data
const getBinLocationDetails = (locationId) => {
  const binLocation = allBinLocations.find(bin => bin.id === locationId);
  return binLocation ? binLocation.bin_location_combine : locationId;
};

// Lookup UOM name from pre-fetched data
const getUOMName = (uomId) => {
  const uom = allUOMs.find(u => u.id === uomId);
  return uom ? uom.uom_name : "";
};

// ============================================================================
// DEDUPLICATION
// ============================================================================
const allocatedFromOtherRows = getCurrentAllocations(
  currentRow.materialId,
  currentRow.rowIndex,
  allocationTracker
);

const adjustedBalances = applyAllocationsToBalances(
  balances,
  allocatedFromOtherRows,
  isBatchManaged
);

// ============================================================================
// ALLOCATION ENGINE - STEP 0: PRIORITIZE PENDING RESERVED DATA
// ============================================================================
let allAllocations = [];
let remainingQty = currentRow.quantity;

// 🔧 NEW: Sort pending reserved data to prioritize Production over Sales Order
if (pendingReservedData.length > 0 && currentRow.soLineItemId) {
  const sortedReservedData = [...pendingReservedData].sort((a, b) => {
    if (a.doc_type === "Production" && b.doc_type !== "Production") return -1;
    if (a.doc_type !== "Production" && b.doc_type === "Production") return 1;
    return 0;
  });

  for (const reservation of sortedReservedData) {
    if (remainingQty <= 0) break;

    const reservedQty = parseFloat(reservation.open_qty || 0);
    if (reservedQty <= 0) continue;

    // Find matching balance by bin_location and batch_id (if batch-managed)
    const matchingBalance = adjustedBalances.find((b) => {
      const binMatch = b.location_id === reservation.bin_location;
      if (isBatchManaged) {
        return binMatch && b.batch_id === reservation.batch_id;
      }
      return binMatch;
    });

    if (matchingBalance) {
      const availableQty = matchingBalance.unrestricted_qty || 0;
      // Allocate min of: remaining qty, reserved qty, available balance
      const allocatedQty = Math.min(remainingQty, reservedQty, availableQty);

      if (allocatedQty > 0) {
        const binLocationName = getBinLocationDetails(matchingBalance.location_id);
        const batchData = isBatchManaged ? findBatchData(matchingBalance.batch_id) : null;

        // Check if already allocated to this location
        const existingAllocIndex = allAllocations.findIndex((a) => {
          const locMatch = a.balance.location_id === matchingBalance.location_id;
          if (isBatchManaged) {
            return locMatch && a.batchData?.id === matchingBalance.batch_id;
          }
          return locMatch;
        });

        if (existingAllocIndex >= 0) {
          allAllocations[existingAllocIndex].quantity += allocatedQty;
        } else {
          allAllocations.push({
            balance: matchingBalance,
            quantity: allocatedQty,
            binLocation: binLocationName,
            batchData: batchData,
            source: `Reserved (${reservation.doc_type})`  // For debugging
          });
        }

        remainingQty -= allocatedQty;
        // Reduce balance for next iteration
        matchingBalance.unrestricted_qty = Math.max(0, matchingBalance.unrestricted_qty - allocatedQty);
      }
    }
  }
}

// ============================================================================
// ALLOCATION ENGINE - STEP 1: APPLY STRATEGY FOR REMAINING QTY
// ============================================================================
if (remainingQty > 0) {
  const defaultBin = getDefaultBin(itemData, currentRow.plantId);
  const defaultStrategy = pickingSetup.default_strategy_id;
  const fallbackStrategy = pickingSetup.fallback_strategy_id;

  // Helper: Sort by FIFO (expired date)
  const sortByFIFO = (balanceArray) => {
    if (!isBatchManaged) return balanceArray;

    return balanceArray.sort((a, b) => {
      const batchA = findBatchData(a.batch_id);
      const batchB = findBatchData(b.batch_id);

      if (batchA?.expired_date && batchB?.expired_date) {
        return new Date(batchA.expired_date) - new Date(batchB.expired_date);
      }

      return (batchA?.batch_number || "").localeCompare(batchB?.batch_number || "");
    });
  };

  // Helper: Allocate from a list of balances
  const allocateFromBalances = (balanceList) => {
    const allocated = [];

    for (const balance of balanceList) {
      if (remainingQty <= 0) break;

      const availableQty = balance.unrestricted_qty || 0;
      if (availableQty <= 0) continue;

      const allocatedQty = Math.min(remainingQty, availableQty);

      const binLocationName = getBinLocationDetails(balance.location_id);
      const batchData = isBatchManaged ? findBatchData(balance.batch_id) : null;

      allocated.push({
        balance: balance,
        quantity: allocatedQty,
        binLocation: binLocationName,
        batchData: batchData,
        source: "Strategy"  // For debugging
      });

      remainingQty -= allocatedQty;
    }

    return allocated;
  };

  // Get already allocated location keys to exclude
  const allocatedKeys = new Set(
    allAllocations.map((a) =>
      isBatchManaged
        ? `${a.balance.location_id}-${a.batchData?.id || "no_batch"}`
        : `${a.balance.location_id}`
    )
  );

  // Filter out already allocated balances
  const remainingBalances = adjustedBalances.filter((b) => {
    const key = isBatchManaged
      ? `${b.location_id}-${b.batch_id || "no_batch"}`
      : `${b.location_id}`;
    return !allocatedKeys.has(key) && (b.unrestricted_qty || 0) > 0;
  });

  // STRATEGY: FIXED BIN
  if (defaultStrategy === "FIXED BIN") {
    // Step 1: Try default bin first (only if configured)
    if (defaultBin) {
      const defaultBinBalances = remainingBalances.filter(
        b => b.location_id === defaultBin
      );

      const sortedDefaultBalances = sortByFIFO(defaultBinBalances);
      const defaultAllocations = allocateFromBalances(sortedDefaultBalances);
      allAllocations.push(...defaultAllocations);
    }

    // Step 2: Fallback to RANDOM for remainder (or if no default bin configured)
    if (remainingQty > 0 && fallbackStrategy === "RANDOM") {
      const otherBalances = remainingBalances.filter(
        b => !defaultBin || b.location_id !== defaultBin
      );

      const sortedOtherBalances = sortByFIFO(otherBalances);
      const fallbackAllocations = allocateFromBalances(sortedOtherBalances);
      allAllocations.push(...fallbackAllocations);
    }
  }
  // STRATEGY: RANDOM
  else if (defaultStrategy === "RANDOM") {
    const sortedBalances = sortByFIFO(remainingBalances);
    const randomAllocations = allocateFromBalances(sortedBalances);
    allAllocations.push(...randomAllocations);
  }
}

// ============================================================================
// BUILD RESULTS
// ============================================================================

// Build temp_qty_data array
const tempQtyData = allAllocations.map(alloc => ({
  material_id: currentRow.materialId,
  location_id: alloc.balance.location_id,
  block_qty: alloc.balance.block_qty,
  reserved_qty: alloc.balance.reserved_qty,
  unrestricted_qty: alloc.balance.original_unrestricted_qty || alloc.balance.unrestricted_qty,
  qualityinsp_qty: alloc.balance.qualityinsp_qty,
  intransit_qty: alloc.balance.intransit_qty,
  balance_quantity: alloc.balance.balance_quantity,
  plant_id: currentRow.plantId,
  organization_id: alloc.balance.organization_id,
  is_deleted: 0,
  to_quantity: alloc.quantity,
  ...(alloc.batchData && { batch_id: alloc.batchData.id })
}));

// Get UOM name from pre-fetched data
const uomName = getUOMName(currentRow.uomId);

// Build view_stock summary
const summaryLines = allAllocations.map((alloc, idx) => {
  let line = `${idx + 1}. ${alloc.binLocation}: ${alloc.quantity} ${uomName}`;
  if (alloc.batchData) {
    line += `\n[${alloc.batchData.batch_number}]`;
  }
  return line;
});

const totalAllocated = allAllocations.reduce((sum, alloc) => sum + alloc.quantity, 0);
const viewStock = totalAllocated > 0
  ? `Total: ${totalAllocated} ${uomName}\n\nDETAILS:\n${summaryLines.join("\n")}`
  : "";

// Update allocation tracker
const updatedTracker = { ...allocationTracker };
if (!updatedTracker[currentRow.materialId]) {
  updatedTracker[currentRow.materialId] = {};
}

const rowAllocations = {};
allAllocations.forEach(alloc => {
  const key = alloc.batchData
    ? `${alloc.balance.location_id}-${alloc.batchData.id}`
    : `${alloc.balance.location_id}`;
  rowAllocations[key] = alloc.quantity;
});

updatedTracker[currentRow.materialId][currentRow.rowIndex] = rowAllocations;

// ============================================================================
// RETURN RESULTS
// ============================================================================
return {
  temp_qty_data: JSON.stringify(tempQtyData),
  view_stock: viewStock,
  total_allocated: totalAllocated,
  rowIndex: currentRow.rowIndex,
  updatedTracker: updatedTracker
};

const rawtableTO = {{node:get_cache_node_XGpEIHGk.data}};
let tableTO = [];

if (rawtableTO) {
  if (typeof rawtableTO === 'string') {
    tableTO = JSON.parse(rawtableTO);
  } else {
    tableTO = rawtableTO;
  }
}

const allocationResult = {{node:code_node_KTHlcvbv.data}};

// Where the allocated row sits. A bundle's items are rows of the tree rather
// than of table_to, so a single position cannot reach them -- prepareAllocationData
// hands over the parent's position plus the item's own, with childIndex null on
// an ordinary line.
const currentRow = {{node:code_node_cvOKI9GU.data.currentRow}} || {};
const parentIndex =
  currentRow.parentIndex !== undefined && currentRow.parentIndex !== null
    ? currentRow.parentIndex
    : allocationResult.rowIndex;
const childIndex =
  currentRow.childIndex !== undefined ? currentRow.childIndex : null;

const parentRow = tableTO[parentIndex];
let targetRow = null;

if (parentRow) {
  if (childIndex === null) {
    targetRow = parentRow;
  } else if (Array.isArray(parentRow.children)) {
    targetRow = parentRow.children[childIndex] || null;
  }
}

// Update specific row
if (targetRow) {
  targetRow.temp_qty_data = allocationResult.temp_qty_data;
  targetRow.view_stock = allocationResult.view_stock;

  const toQty = parseFloat(targetRow.to_qty) || 0;
  const initialDeliveredQty = parseFloat(targetRow.to_initial_delivered_qty) || 0;
  const orderedQty = parseFloat(targetRow.to_order_quantity) || 0;

  targetRow.to_delivered_qty = initialDeliveredQty + toQty;
  targetRow.to_undelivered_qty = orderedQty - (initialDeliveredQty + toQty);
} else {
  console.log("allocation target row not found", parentIndex, childIndex);
}

return {
  tableTO: tableTO,
  updatedTracker: allocationResult.updatedTracker
};

const allData = {{workflowparams:allData}};
const totalRowsToAllocate = {{node:code_node_C58lS8pM.data.totalRowsToAllocate}};

// If no rows were allocated, just return original table_to
if (totalRowsToAllocate === 0) {
  return { tableTO: allData.table_to };
}

// Otherwise, get the allocated table from Redis
const rawTableTo = {{node:get_cache_node_CBiQBoVP.data}};

let tableTO = [];
if (typeof rawTableTo === 'string') {
  tableTO = JSON.parse(rawTableTo);
} else {
  tableTO = rawTableTo || allData.table_to;
}

return { tableTO };

// Line ids for the reservation lookup below. An empty `equalAny` list matches
// EVERYTHING, so an empty plan sends a value that matches nothing instead --
// the same sentinel code_node_CancelPPReset uses.
const rawBefore = {{node:get_node_zG6KDDEF.data.data}};
const before = Array.isArray(rawBefore)
  ? rawBefore[0] || null
  : rawBefore || null;

const flattenRows = (rows) =>
  (rows || []).flatMap((row) => [
    row,
    ...(Array.isArray(row.children) ? row.children : [])
  ]);

const lineIds = [];
for (const row of flattenRows(before && before.table_to)) {
  if (row && row.id) lineIds.push(String(row.id));
}
if (lineIds.length === 0) lineIds.push("__none__");

const ppId = String((before && before.id) || "");

return {
  lineIds: lineIds,
  // Two shapes on purpose. `to_no` is a json array column and every working
  // filter against that shape in this repo uses `in` with a SCALAR, so that is
  // what the picking lookup gets; the array form is kept for equalAny filters.
  ppId: ppId ? [ppId] : ["__none__"],
  ppIdScalar: ppId || "__none__"
};

// Can this plan be edited now that picking has started?
//
// The plan is NOT reconciled against its Picking the way a delivery is. Raising a
// quantity leaves the existing Picking alone and the outstanding balance is picked
// by converting a second one -- PPconvertToPicking already subtracts
// picked_temp_qty_data and offers only the remainder. Everything that cannot be
// expressed that way is refused rather than unwound.
const saveAs = {{workflowparams:saveAs}};
const isPicking = {{workflowparams:isPicking}};
const allData = {{workflowparams:allData}};

const rawBefore = {{node:get_node_zG6KDDEF.data.data}};
const before = Array.isArray(rawBefore)
  ? rawBefore[0] || null
  : rawBefore || null;

const rawRes = {{node:search_node_pp_reserved.data.data}};
const reservations = Array.isArray(rawRes) ? rawRes : rawRes ? [rawRes] : [];

const rawPick = {{node:search_node_pp_pickings.data.data}};
const pickings = Array.isArray(rawPick) ? rawPick : rawPick ? [rawPick] : [];

const rawGd = {{node:search_node_pp_gd_claims.data.data}};
const gdClaims = Array.isArray(rawGd) ? rawGd : rawGd ? [rawGd] : [];

const OFF = {
  blockEdit: 0,
  blockMessage: "",
  lineStatusOverrides: {},
  headerPickingStatus: ""
};

// The Picking re-invokes this workflow with isPicking set; it must pass straight
// through, exactly as the old guard allowed.
if (saveAs !== "Created" || isPicking || !before || !allData) {
  return OFF;
}

const roundQty = (v) => Math.round((parseFloat(v) || 0) * 1000) / 1000;
const ppId = String(before.id || "");

const flattenRows = (rows) =>
  (rows || []).flatMap((row) => [
    row,
    ...(Array.isArray(row.children) ? row.children : [])
  ]);

// Read the STORED plan, not the submitted one. A page opened before the picker
// started carries a stale picking_status -- the guard this replaces read
// allData.picking_status and could be talked out of firing.
const beforeLines = flattenRows(before.table_to).filter((r) => r && r.material_id);
const afterLines = flattenRows(allData.table_to).filter((r) => r && r.material_id);

const afterById = {};
for (const row of afterLines) {
  if (row.id) afterById[String(row.id)] = row;
}

const anyPicked = beforeLines.some((r) => roundQty(r.picked_qty) > 0);
const priorStatus = String(before.picking_status || "");
const started =
  priorStatus === "In Progress" || priorStatus === "Completed" || anyPicked;

// A Picking that exists but has not been picked yet is just as dangerous as a
// picked one for removals and reductions: nothing ever updates an existing
// Picking's qty_to_pick, so the row is left describing a plan line that no longer
// says that -- production already holds 8 picking rows pointing at plan lines that
// were deleted. Worse, reducing below an open Picking's quantity makes that Picking
// permanently unclosable, because code_node_AGoxWP7x refuses "Picked quantity
// cannot exceed plan quantity" before it writes anything.
const openPicking = pickings.some(
  (p) => String(p.to_status || "") === "Created"
);

if (!started && !openPicking) {
  return OFF;
}

const pickingNo = pickings.length
  ? String(pickings[0].to_id || pickings[0].id)
  : "the Picking";

const block = (message) => ({
  blockEdit: 1,
  blockMessage: message,
  lineStatusOverrides: {},
  headerPickingStatus: ""
});

// A Picking mid-confirm is writing these very lines from the other side. Only an
// open Picking can be mid-confirm; the flag leaks on terminal ones (8 stale rows in
// production, all Completed or Cancelled) and honouring those would lock a plan for
// good with no way to clear it.
for (const p of pickings) {
  if (String(p.to_status || "") === "Created" && Number(p.is_processing || 0) !== 0) {
    return block(
      "Picking " +
        String(p.to_id || p.id) +
        " is being processed on a device right now. Try again in a moment."
    );
  }
}

// A delivery built from this plan takes the reservation over: doc_type stays
// "Picking Plan" but target_gd_id is restamped to the delivery. Once that has
// happened the delivery also holds picking_record_id references into the pick
// records, so changing the plan underneath it would leave the delivery describing
// stock that no longer adds up.
const claimedByLine = {};
for (const res of reservations) {
  const line = String(res.doc_line_id || "");
  if (!line) continue;
  const status = String(res.status || "");
  const target = String(res.target_gd_id || "");
  if (status === "Delivered" || (target && target !== ppId)) {
    claimedByLine[line] = 1;
  }
}

// Reservations alone are not enough. A delivery built from this plan and saved as
// Created is a deliberate no-inventory middle state -- code_node_b71wypDJ returns
// early and writes no reservation row at all -- so its claim is invisible above
// while it holds picking_record_id references into the pick records. Production has
// 64 such delivery lines. The delivery line itself is the only evidence.
for (const g of gdClaims) {
  const line = String(g.pp_line_item_id || "");
  if (line) claimedByLine[line] = 1;
}

const lineStatusOverrides = {};
let allDone = true;
let anyProgress = false;
let anyLive = false;

for (const line of beforeLines) {
  const id = String(line.id || "");
  if (!id) continue;
  const picked = roundQty(line.picked_qty);
  const label = line.material_name || line.to_material_desc || id;
  const after = afterById[id];

  if (picked > 0 && claimedByLine[id]) {
    return block(
      "Item " +
        label +
        " has already been taken by a Goods Delivery, so this plan can no longer be changed. Revert and cancel that delivery first."
    );
  }

  if ((picked > 0 || openPicking) && !after) {
    return block(
      picked > 0
        ? "Item " + label + " already has " + picked + " picked on " + pickingNo +
          " and cannot be removed. Cancel or revert the Picking first."
        : "Item " + label + " is on Picking " + pickingNo +
          ", which is still open, so it cannot be removed. Cancel that Picking first."
    );
  }

  if (
    (picked > 0 || openPicking) &&
    after &&
    String(after.material_id || "") !== String(line.material_id || "")
  ) {
    return block(
      "Item " +
        label +
        " already has " +
        picked +
        " picked on " +
        pickingNo +
        ", so the item on that row cannot be changed. Cancel or revert the Picking first."
    );
  }

  if (!after) continue;

  const desired = roundQty(after.to_qty);
  const floor = openPicking ? Math.max(picked, roundQty(line.to_qty)) : picked;
  if (desired < floor) {
    return block(
      picked > 0
        ? "Item " + label + " has " + picked + " picked on " + pickingNo +
          " but the plan now asks for " + desired +
          ". Cancel or revert the Picking before reducing it."
        : "Item " + label + " is planned as " + floor + " on Picking " + pickingNo +
          ", which is still open. Reducing it to " + desired +
          " would leave that Picking impossible to close. Cancel it first."
    );
  }

  // The allocation may have been rewritten since the pick -- the quantity handler
  // and the stock dialog both rebuild temp_qty_data and neither knows what has
  // been picked. PPconvertToPicking works out what is left to pick by subtracting
  // picked_temp_qty_data from temp_qty_data key by key, so a key dropped here
  // comes back as quantity to pick a second time: stock already off the shelf.
  if (picked > 0) {
    const parseAlloc = (raw) => {
      if (Array.isArray(raw)) return raw;
      if (!raw) return [];
      try {
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : [];
      } catch (e) {
        return [];
      }
    };
    const allocKey = (e) =>
      String(e.location_id || "") +
      "|" +
      String(e.batch_id || "") +
      "|" +
      String(e.handling_unit_id || "");

    const pickedBy = {};
    for (const e of parseAlloc(line.picked_temp_qty_data)) {
      const q = roundQty(e.to_quantity);
      if (q > 0) {
        const k = allocKey(e);
        pickedBy[k] = roundQty((pickedBy[k] || 0) + q);
      }
    }

    const pickedKeys = Object.keys(pickedBy);
    if (pickedKeys.length) {
      const plannedBy = {};
      for (const e of parseAlloc(after.temp_qty_data)) {
        const q = roundQty(e.to_quantity);
        if (q > 0) {
          const k = allocKey(e);
          plannedBy[k] = roundQty((plannedBy[k] || 0) + q);
        }
      }
      for (const key of pickedKeys) {
        if (roundQty(plannedBy[key]) < pickedBy[key]) {
          return block(
            "Item " +
              label +
              " has " +
              pickedBy[key] +
              " already picked from a bin and batch the plan no longer allocates. Allocate that quantity back to the same bin, or cancel or revert Picking " +
              pickingNo +
              " first."
          );
        }
      }
    }
  }

  // A line delivered straight to a Goods Delivery without ever being picked reads
  // Completed with nothing picked. Recomputing would send it back to Created and
  // re-offer it for picking, so leave it exactly as it is.
  if (picked === 0 && String(line.picking_status || "") === "Completed") {
    continue;
  }

  // Recompute the line's picking_status against the NEW quantity. Without this a
  // raised line still reads Completed from when the quantity was lower, and
  // PPconvertToPicking skips Completed lines -- so the outstanding balance could
  // never be converted.
  if (desired > 0) {
    anyLive = true;
    if (picked >= desired) {
      lineStatusOverrides[id] = "Completed";
    } else if (picked > 0) {
      lineStatusOverrides[id] = "In Progress";
      allDone = false;
      anyProgress = true;
    } else {
      lineStatusOverrides[id] = "Created";
      allDone = false;
    }
    if (picked > 0) anyProgress = true;
  }
}

const headerPickingStatus = !anyLive
  ? ""
  : allDone
    ? "Completed"
    : anyProgress
      ? "In Progress"
      : "Created";

return {
  blockEdit: 0,
  blockMessage: "",
  lineStatusOverrides: lineStatusOverrides,
  headerPickingStatus: headerPickingStatus
};

let allData = {{workflowparams:allData}};
const updatedTO = [];
const saveAs = {{workflowparams:saveAs}};
const pickingSetup = {{node:get_node_MX4rxQLm.data.data}};
const pageStatus = {{workflowparams:pageStatus}}
const isForceComplete = {{workflowparams:isForceComplete}} || 0;

const skippedRows = [];

if (pickingSetup?.picking_mode === "Auto" && saveAs !== "Cancelled") {
  const tableTO = {{node:code_node_fsjJarKT.data.tableTO}}
  if (tableTO?.length > 0) {
    allData.table_to = tableTO
  }
}

// ============================================================================
// ITEM BUNDLES
// ----------------------------------------------------------------------------
// A bundle is ONE row of table_to with the bundle's items under `children`, the
// same shape the sales order carries. The bundle row is not an item -- it holds
// no material, owns no stock and nothing is ever allocated against it, so it can
// never carry temp_qty_data and must not be judged by it. Its items are ordinary
// lines in every other respect: they are stamped, quantity-checked and planned
// exactly like a top-level row.
// ============================================================================
const isBundleParent = (row) => Boolean(row.item_bundle_id) && !row.material_id;
const childrenOf = (row) => (Array.isArray(row.children) ? row.children : []);
const roundQty = (value) => Math.round((parseFloat(value) || 0) * 1000) / 1000;

// A bundle is planned as a whole: every item under it is the bundle's own
// quantity times the number of bundles planned. Planning 2 of item A against 1
// of item B, when the bundle holds one of each, is not a bundle -- and the form
// is the only thing stopping it, so anything reaching this workflow by another
// route (a headless save, an API call, a stale page) would persist it.
//
// The rate comes off the plan rather than out of the bundle: a child ordered N
// times the bundle's own order quantity is N per bundle. That is the same ratio
// the bundle defines, already carried on every row, so no lookup is needed.
const bundleRatioProblem = (parent, child) => {
  const bundlesOrdered = parseFloat(parent.to_order_quantity) || 0;

  // Nothing to derive a rate from -- leave the line alone rather than guess.
  if (bundlesOrdered <= 0) return null;

  const perBundleQty =
    (parseFloat(child.to_order_quantity) || 0) / bundlesOrdered;
  const expected = roundQty(perBundleQty * (parseFloat(parent.to_qty) || 0));
  const actual = roundQty(child.to_qty);

  return Math.abs(actual - expected) > 0.001 ? { expected, actual } : null;
};

// Every row of the document -- top-level rows and the items under a bundle.
const flattenRows = (rows) =>
  (rows || []).flatMap((row) => [row, ...childrenOf(row)]);

// The allocation a line must carry to be planned. Returns null when the line is
// good, otherwise the reason it cannot be saved. A bundle row never reaches this.
const allocationProblem = (row) => {
  const tempQtyData = row.temp_qty_data;
  const isEmpty =
    !tempQtyData ||
    tempQtyData === "" ||
    tempQtyData === "[]" ||
    tempQtyData === null;

  if (isEmpty) {
    return { reason: "temp_qty_data is empty" };
  }

  try {
    const parsedTempQty = JSON.parse(tempQtyData);
    const totalAllocated = parsedTempQty.reduce(
      (sum, item) => sum + (parseFloat(item.to_quantity) || 0),
      0
    );
    const toQty = parseFloat(row.to_qty) || 0;

    if (Math.abs(totalAllocated - toQty) > 0.001) {
      return {
        allocated_qty: totalAllocated,
        reason: `temp_qty_data total (${totalAllocated}) != to_qty (${toQty})`,
      };
    }
  } catch (e) {
    return { reason: "temp_qty_data parse error" };
  }

  return null;
};

// The header fields every line carries, parent and child alike. `lineIndex`
// mirrors the sales order: a plain number on a top-level row, `parent/child` on
// an item under a bundle.
const stampLine = (row, lineIndex, isBundle) => {
  row.customer_id = allData.customer_name || null;
  row.organization_id = allData.organization_id;
  row.plant_id = allData.plant_id || null;
  row.billing_state_id = allData.billing_address_state || null;
  row.billing_country_id = allData.billing_address_country || null;
  row.shipping_state_id = allData.shipping_address_state || null;
  row.shipping_country_id = allData.shipping_address_country || null;
  row.assigned_to = allData.assigned_to || null;
  row.line_index = lineIndex;

  if (saveAs === "Cancelled") {
    row.picking_status = row.picking_status ? "Cancelled" : null;
  }

  // Nothing is picked against a bundle row, so it takes no picking status --
  // it would otherwise sit at "Created" for ever while its items complete.
  if (
    !isBundle &&
    pickingSetup &&
    (!allData.picking_status || allData.picking_status === "") &&
    saveAs === "Created" &&
    pickingSetup.picking_required === 1
  ) {
    if (pickingSetup.auto_trigger_to === 1) {
      row.picking_status = "Created";
    } else {
      row.picking_status = "Not Created";
    }
  }

  if (isForceComplete === 1) {
    row.temp_qty_data = row.picked_temp_qty_data;
    row.view_stock = row.picked_view_stock;
    row.to_qty = row.picked_qty;
  }
};

for (const [index, toLineItem] of allData.table_to.entries()) {
  if (isBundleParent(toLineItem)) {
    // The bundle row is kept for whichever of its items still have something to
    // plan; if none do, the whole bundle drops out together.
    const keptChildren = [];

    for (const [childIndex, child] of childrenOf(toLineItem).entries()) {
      const ratio = bundleRatioProblem(toLineItem, child);

      if (ratio) {
        skippedRows.push({
          index: index,
          kind: "bundle",
          line_label: `${index + 1}/${childIndex + 1}`,
          material_name: child.material_name || "Unknown",
          to_qty: child.to_qty,
          so_no: child.so_no || "",
          reason: `item bundle quantities must stay in proportion - expected ${ratio.expected}, got ${ratio.actual}`,
        });
        continue;
      }

      if (!child.to_qty || parseFloat(child.to_qty) === 0) {
        continue;
      }

      const problem = allocationProblem(child);

      if (problem) {
        skippedRows.push({
          index: index,
          line_label: `${index + 1}/${childIndex + 1}`,
          material_name: child.material_name || "Unknown",
          to_qty: child.to_qty,
          allocated_qty: problem.allocated_qty,
          so_no: child.so_no || "",
          reason: problem.reason,
        });
        continue;
      }

      stampLine(child, `${index + 1}/${keptChildren.length + 1}`, false);
      keptChildren.push(child);
    }

    if (keptChildren.length === 0) {
      continue;
    }

    toLineItem.children = keptChildren;
    stampLine(toLineItem, index + 1, true);
    updatedTO.push(toLineItem);
    continue;
  }

  if (!toLineItem.to_qty || parseFloat(toLineItem.to_qty) === 0) {
    continue;
  }

  const problem = allocationProblem(toLineItem);

  if (problem) {
    skippedRows.push({
      index: index,
      line_label: `${index + 1}`,
      material_name: toLineItem.material_name || "Unknown",
      to_qty: toLineItem.to_qty,
      allocated_qty: problem.allocated_qty,
      so_no: toLineItem.so_no || "",
      reason: problem.reason,
    });
    continue;
  }

  stampLine(toLineItem, index + 1, false);
  updatedTO.push(toLineItem);
}

allData.table_to = updatedTO;

if ({{workflowparams:pageStatus}} === "Add") {
  allData.to_status = "Draft";
}

if (
  pickingSetup &&
  (!allData.picking_status || allData.picking_status === "") &&
  saveAs === "Created" &&
  pickingSetup.picking_required === 1
) {
  if (pickingSetup.auto_trigger_to === 1) {
    allData.picking_status = "Created";
  } else {
    allData.picking_status = "Not Created";
  }
}

if (saveAs !== "Cancelled") {
  if (saveAs === "Draft") {
    if (
      allData.to_no_type !== -9999 &&
      (!allData.to_no ||
        allData.to_no === null ||
        allData.to_no === "")
    ) {
      allData.to_no = "draft";
    }
  } else {
    if (
      allData.to_no_type !== -9999 &&
      (!allData.to_no ||
        allData.to_no === null ||
        allData.to_no === "" ||
        allData.to_status === "Draft")
    ) {
      allData.to_no = "issued";
    }
  }
}

if (saveAs === "Cancelled") {
  allData.picking_status = allData.picking_status ? "Cancelled" : null;
  allData.to_no = allData.to_no + "-Cancelled";
}

let needSOCleanUp = 0

if (allData.to_status === "Created") {
  const originalTO = {{node:get_node_zG6KDDEF.data.data}};

  // Matched across the whole tree: a bundle's items are lines in their own
  // right and carry their own allocation, they are just not top-level rows.
  const originalRows = flattenRows(originalTO.table_to);

  flattenRows(allData.table_to).forEach((item) => {
    const originalItem = originalRows.find(
      orig => orig.so_line_item_id === item.so_line_item_id
    );
    if (originalItem) {
      item.prev_temp_qty_data = originalItem.temp_qty_data;
    }
  });

  if (flattenRows(allData.table_to).length !== originalRows.length) {
    needSOCleanUp = 1
  }
}

let invalidData = 0;
let invalidDataMessage = "";

if (skippedRows.length > 0) {
  invalidData = 1;

  const rowDetails = skippedRows.map(row => 
    `Row ${row.line_label}: ${row.material_name} - qty: ${row.to_qty}${row.allocated_qty !== undefined ? `, allocated: ${row.allocated_qty}` : ""}${row.so_no ? ` [SO: ${row.so_no}]` : ""} — ${row.reason}`
  ).join("\n");

  const hasAllocationProblem = skippedRows.some((row) => row.kind !== "bundle");

  const hint = hasAllocationProblem
    ? "These rows may need manual allocation or the allocation workflow may have failed."
    : "Plan an item bundle by its bundle line - its items follow from it and cannot be planned on their own.";

  invalidDataMessage = `Warning: ${skippedRows.length} row(s) skipped due to invalid data:\n\n${rowDetails}\n\n${hint}`;
}

return {
  allData: allData,
  to_status: allData.to_status,
  picking_status: allData.picking_status === "" ? null : allData.picking_status,
  packing_status: allData.packing_status,
  needSOCleanUp: needSOCleanUp,
  invalidData: invalidData,
  invalidDataMessage: invalidDataMessage,
  isForceComplete: isForceComplete || 0,
};

return {
  required_fields: JSON.stringify([
    { name: "customer_name", label: "Customer" },
    { name: "plant_id", label: "Plant" },
    { name: "so_id", label: "Sales Order" },
    { name: "to_no", label: "Transfer Order Number" },
    {
        name: "table_to",
        label: "Item Table",
        isArray: true,
        arrayType: "object",
        arrayFields: [],
    },
]),
  data: JSON.stringify({
    customer_name: {{node:code_node_Nj60Z2XF.data.allData.customer_name}},
    plant_id: {{node:code_node_Nj60Z2XF.data.allData.plant_id}},
    so_id: {{node:code_node_Nj60Z2XF.data.allData.so_id}},
    to_no: {{node:code_node_Nj60Z2XF.data.allData.to_no}},
    table_to: {{node:code_node_Nj60Z2XF.data.allData.table_to}}
  })
}

const pickingSetup = {{node:get_node_MX4rxQLm.data.data}} || {};
const saveAs = {{workflowparams:saveAs}}
const pageStatus = {{workflowparams:pageStatus}}
let picking_status = {{node:code_node_Nj60Z2XF.data.picking_status}}

if (pickingSetup && (!picking_status || picking_status === "") && saveAs === "Created" && pickingSetup.picking_required === 1) {
  if (pickingSetup.auto_trigger_to === 1) {
