}

return {
  picking_status: picking_status,
  auto_trigger_to: pickingSetup.auto_trigger_to
}

const allData = {{node:code_node_Nj60Z2XF.data.allData}}

// Everything below this point works one line at a time -- quantity check,
// inventory check, and the planned_qty written back to the sales order line. A
// bundle keeps its items under `children`, and those items are ordinary lines
// in all three respects, so the tree is walked flat here and the loop covers
// them without knowing anything about bundles.
//
// The bundle row itself is dropped: it holds no material and owns no stock, and
// its sales order line is a header rather than a quantity, so it takes no
// planned_qty and no delivered_qty. Completion is decided by its items.
const isBundleParent = (row) => Boolean(row.item_bundle_id) && !row.material_id;

const tableTO = (allData.table_to || []).flatMap((row) => [
  ...(isBundleParent(row) ? [] : [row]),
  ...(Array.isArray(row.children) ? row.children : []),
]);

return {
  tableTO: tableTO
};

// Helper function to safely parse JSON
const parseJsonSafely = (jsonString, defaultValue = []) => {
  try {
    return jsonString ? JSON.parse(jsonString) : defaultValue;
  } catch (error) {
    console.error("JSON parse error:", error);
    return defaultValue;
  }
};

const tableTO = {{node:code_node_XBdTDPyC.data.tableTO}}
const currentIndexRaw = {{node:get_cache_node_g7OZa1LU.data}}
const index = currentIndexRaw ? parseInt(currentIndexRaw, 10) : 0

const toItem = tableTO[index];
const material_id = toItem.material_id;
const parentLineId = toItem.so_line_item_id;
const toQty = toItem.to_qty;
const tempData = parseJsonSafely(toItem.temp_qty_data);

let originalToItem = null
const to_status = {{node:code_node_Nj60Z2XF.data.to_status}}

if (to_status === "Created") {
  const originalTableTO = {{node:get_node_zG6KDDEF.data.data.table_to}}

  // A bundle's items are lines in their own right -- they just sit under their
  // bundle rather than in table_to -- so the previous plan is matched across the
  // whole tree. Without this an item under a bundle looks brand new on every
  // re-save and its planned_qty is added a second time.
  const originalRows = (originalTableTO || []).flatMap((row) => [
    row,
    ...(Array.isArray(row.children) ? row.children : []),
  ]);

  originalToItem = originalRows.find(item => item.so_line_item_id === toItem.so_line_item_id) || null;
}

return {
