}

const toItem = {{node:code_node_HTffa1le.data.toItem}}
const originalToItem = {{node:code_node_HTffa1le.data.originalToItem}}
const itemData = {{node:get_node_O9yrpVRh.data.data}}
const soItem = {{node:get_node_ZZ6RV7vD.data.data}}
const rowIndex = {{node:code_node_HTffa1le.data.nextIndex}}
const to_status = {{node:code_node_Nj60Z2XF.data.to_status}}
const saveAs = {{workflowparams:saveAs}}

const orderLimit = (toItem.to_order_quantity * (100 + (((itemData.table_uom_conversion || []).find((c) => c.alt_uom_id === toItem.to_order_uom_id) || {}).over_delivery_tolerance || 0))) / 100;
const deliveredQty = soItem.delivered_qty || 0;
const plannedQty = soItem.planned_qty || 0;

// Returns number for calculations/validation
const roundQty = (value) => {
  if (value === null || value === undefined || value === "") return 0;
  const num = parseFloat(value);
  return Math.round(num * 1000) / 1000;
};

// Returns string for database updates
const formatNumber = (value) => {
  if (value === null || value === undefined || value === "") return "0.000";
  return parseFloat(value).toFixed(3);
};

// FIX: Parse to_qty as number to avoid string concatenation
const currentToQty = parseFloat(toItem.to_qty) || 0;
const origQty = parseFloat(originalToItem?.to_qty) || 0;

let toQtyChange = currentToQty;
if (originalToItem) {
  toQtyChange = roundQty(currentToQty - origQty);
}

const totalCommitted = roundQty(deliveredQty + plannedQty + toQtyChange);

let validationMessage = null
if (totalCommitted > orderLimit && saveAs !== "Cancelled") {
  validationMessage = `Row ${rowIndex} with Item ${itemData.material_code} validation failed: quantity is exceeding the maximum deliverable quantity.`
}

let updatedSOTable = {{node:get_cache_node_Hoq75ul3.data}}
if (typeof updatedSOTable === 'string') {
  try {
    updatedSOTable = JSON.parse(updatedSOTable)
  } catch (e) {
    updatedSOTable = []
  }
}
if (!Array.isArray(updatedSOTable)) {
  updatedSOTable = []
}
let updatedSOItem = {{node:get_node_ZZ6RV7vD.data.data}}

if (to_status === "Draft" && saveAs === "Completed") {
  updatedSOItem.delivered_qty = formatNumber(deliveredQty + currentToQty)
  updatedSOItem.outstanding_quantity = formatNumber(updatedSOItem.so_quantity - updatedSOItem.delivered_qty)

} else if (to_status === "Draft" && saveAs === "Created") {
  updatedSOItem.planned_qty = formatNumber(plannedQty + currentToQty)

} else if (to_status === "Created" && saveAs === "Completed") {
  updatedSOItem.planned_qty = formatNumber(plannedQty - origQty)
  updatedSOItem.delivered_qty = formatNumber(deliveredQty + currentToQty)
  updatedSOItem.outstanding_quantity = formatNumber(updatedSOItem.so_quantity - updatedSOItem.delivered_qty)

} else if (to_status === "Created" && saveAs === "Created") {
  updatedSOItem.planned_qty = formatNumber(plannedQty - origQty + currentToQty)

} else if (saveAs === "Cancelled" && to_status === "Created") {
  updatedSOItem.planned_qty = formatNumber(plannedQty - currentToQty)
}

if (saveAs === "Completed") {
  if (updatedSOItem.outstanding_quantity > 0) {
    updatedSOItem.line_status = "Processing"
  } else {
    updatedSOItem.line_status = "Completed"
  }
}

updatedSOTable.push(updatedSOItem)

return {
  validationMessage: validationMessage,
  updatedSOTable: updatedSOTable
}

const tempData = {{node:code_node_HTffa1le.data.tempData}};
const itemData = {{node:get_node_O9yrpVRh.data.data}};
const toItem = {{node:code_node_HTffa1le.data.toItem}};
const currentIndexRaw = {{node:get_cache_node_JXLovQw0.data}};
const index = currentIndexRaw ? parseInt(currentIndexRaw, 10) : 0;
const rowIndex = {{node:code_node_HTffa1le.data.nextIndex}};

const roundQty = (value) => parseFloat(parseFloat(value || 0).toFixed(3));

if (itemData.stock_control === 0) {
  return { skipValidation: 1, nextIndex: index + 1 };
}

const isBatchManagedItem = itemData.item_batch_management === 1 ? 1 : 0;
const tempItem = tempData[index];
const batch_id = isBatchManagedItem === 1 ? tempItem.batch_id : null;
const location_id = tempItem.location_id;
let to_quantity = roundQty(tempItem.to_quantity);

if (Array.isArray(itemData.table_uom_conversion) && itemData.table_uom_conversion.length > 0) {
  const uomConversion = itemData.table_uom_conversion.find(
